type Result<T, E = string> = { ok: true; data: T } | { ok: false; error: E };
type Galat = "kosong" | "terlalu-pendek" | "tanpa-angka";

function cekSandi(s: string): Result<string, Galat> {
  if (s === "") return { ok: false, error: "kosong" };
  if (s.length < 8) return { ok: false, error: "terlalu-pendek" };
  if (!/[0-9]/.test(s)) return { ok: false, error: "tanpa-angka" };
  return { ok: true, data: s };
}
const PESAN: Record<Galat, string> = {
  kosong: "Sandi wajib diisi",
  "terlalu-pendek": "Minimal 8 karakter",
  "tanpa-angka": "Harus ada angka",
};
for (const s of ["rahasia", "rahasiasekali", "rahasia123"]) {
  const h = cekSandi(s);
  console.log(h.ok ? "OK " + h.data.length : PESAN[h.error]);
}

