type Result<T> = { ok: true; data: T } | { ok: false; error: string };
function cariStok(kode: string): Result<number> {
  const stok: Record<string, number> = { P01: 12, P02: 0 };
  if (!(kode in stok)) return { ok: false, error: "Produk tidak ada" };
  return { ok: true, data: stok[kode] };
}
const a = cariStok("P01");
if (a.ok) console.log("Stok:", a.data);
const b = cariStok("P09");
if (b.ok) console.log("Stok:", b.data);
else console.log("Gagal:", b.error);
function pesan(kode: string, jumlah: number): Result<number> {
  const s = cariStok(kode);
  if (!s.ok) return s;
  if (s.data < jumlah) return { ok: false, error: "Stok kurang" };
  return { ok: true, data: s.data - jumlah };
}
const c = pesan("P02", 1);
console.log(c.ok ? "Sisa: " + c.data : "Gagal: " + c.error);

