console.log(h.data);

type Result<T> = { ok: true; data: T } | { ok: false; error: string };
function akar(n: number): Result<number> {
  return n < 0 ? { ok: false, error: "negatif" } : { ok: true, data: Math.sqrt(n) };
}
for (const n of [16, -4]) {
  const h = akar(n);
  console.log(h.ok ? h.data : h.error);
}

