type Result<T> = { ok: true; data: T } | { ok: false; error: string };
function parseUmur(teks: string): Result<number> {
  const n = Number(teks);
  if (Number.isNaN(n)) return { ok: false, error: "bukan angka" };
  if (n < 13) return { ok: false, error: "terlalu muda" };
  return { ok: true, data: n };
}
for (const t of ["abc", "10", "21"]) {
  const h = parseUmur(t);
  console.log(h.ok ? h.data : h.error);
}
